for num,name,caption in [(1,'03_data','Locations and observed-month support of the retained cohort. Colors identify the five fixed outer folds. Coordinates are plotted without a geographic basemap or area interpretation. Histograms are normalized separately within each class.'),(2,'01_primary','Primary comparisons at 20% and 100% training labels. Large points are means of three pooled out-of-fold macro-F1 values; error bars show their sample standard deviations. Smaller points are individual seeds. These bars are not confidence intervals.'),(3,'02_controls','Low-label controls and paired comparisons. Left: macro-F1 mean and seed standard deviation. Right: SSL-minus-comparator differences with 2,000-draw paired spatial-component bootstrap percentile intervals. Only the short-Transformer contrast is primary; other intervals are exploratory and conditional on the fixed fits.')]:
    add('figure',caption=f'Figure {num}. {caption}',path=f'paper/figures/{name}.png')
if v6 is not None and (ROOT/'paper/figures/04_label_curve.png').exists():
    add('figure',caption='Figure 4. Label-budget curve on the frozen folds. Points are means of three pooled out-of-fold macro-F1 values; bars are seed standard deviations, not confidence intervals. The 20% and 100% points are the paper_v4 fits; 5%, 10% and 50% are the declared paper_v6 fits.',path='paper/figures/04_label_curve.png')
if v5 is not None and (ROOT/'paper/figures/05_radius.png').exists():
    add('figure',caption='Figure 5. Grouping-radius sensitivity at 20% labels, seed 7 only. Each bar is a single pooled out-of-fold macro-F1; the number of spatial components and clear-cut components per radius is given below the axis. Descriptive only.',path='paper/figures/05_radius.png')
(ROOT/'paper/manuscript_content.json').write_text(json.dumps(blocks,indent=2,ensure_ascii=False))
md=[]
for b in blocks:
    k=b['kind']
    if k=='title':md.append('# '+b['text'])
    elif k=='heading':md.append('## '+b['text'])
    elif k=='paragraph':md.append(b['text'])
    elif k=='table':md.extend([b['caption'], '\n'.join(['| '+' | '.join(b['headers'])+' |','| '+' | '.join(['---']*len(b['headers']))+' |']+['| '+' | '.join(row)+' |' for row in b['rows']])])
    elif k=='figure':md.extend([f"![{b['caption']}](figures/{Path(b['path']).name})",b['caption']])
(ROOT/'paper/manuscript.md').write_text('\n\n'.join(md)+'\n')
print('Composed manuscript from verified analysis:',len(blocks),'blocks')
